// "This month" / "last month" / "this week" windows, computed from the real
// clock (the backend stamps transactions with the server's actual date via
// chama_util:today/0, so these need to track it rather than a fixed demo date).
const pad2 = (n) => String(n).padStart(2, "0");
const isoDate = (d) => `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`;
const TODAY = new Date();
const TODAY_STR = isoDate(TODAY);
const CURRENT_MONTH_PREFIX = TODAY_STR.slice(0, 7);
const LAST_MONTH_DATE = new Date(TODAY.getFullYear(), TODAY.getMonth() - 1, 1);
const LAST_MONTH_PREFIX = `${LAST_MONTH_DATE.getFullYear()}-${pad2(LAST_MONTH_DATE.getMonth() + 1)}`;
const WEEK_AGO_STR = isoDate(new Date(TODAY.getFullYear(), TODAY.getMonth(), TODAY.getDate() - 6));

/* ============================================================
   HARAMBEE RING — signature glyph / progress ring
============================================================ */
function HarambeeMark({ size = 34 }) {
  return (
    <div
      style={{
        width: size, height: size, background: "#fff", borderRadius: size * 0.28,
        display: "flex", alignItems: "center", justifyContent: "center",
        boxShadow: "0 1px 2px rgba(16,24,40,0.12)", flexShrink: 0,
      }}
    >
      <img src={LOGO_DATA_URI} alt="Association logo" style={{ width: size * 0.72, height: size * 0.72, objectFit: "contain" }} />
    </div>
  );
}

function CollectionRing({ pct, size = 108, label, sub }) {
  const r = 44;
  const c = 2 * Math.PI * r;
  const clamped = Math.max(0, Math.min(100, pct));
  return (
    <div className="flex items-center gap-4">
      <svg width={size} height={size} viewBox="0 0 100 100">
        <circle cx="50" cy="50" r={r} stroke="#E4E7EC" strokeWidth="8" fill="none" />
        <circle
          cx="50" cy="50" r={r} stroke="#C89B4C" strokeWidth="8" fill="none"
          strokeDasharray={c} strokeDashoffset={c - (clamped / 100) * c}
          strokeLinecap="round" transform="rotate(-90 50 50)"
        />
        <text x="50" y="47" textAnchor="middle" fontSize="20" fontWeight="700" fill="#101828" style={{ fontFamily: "Fraunces" }}>
          {clamped}%
        </text>
        <text x="50" y="63" textAnchor="middle" fontSize="8" fill="#5B6472">collected</text>
      </svg>
      <div>
        <div className="text-sm font-semibold" style={{ color: "#101828" }}>{label}</div>
        <div className="text-xs mt-0.5" style={{ color: "#5B6472" }}>{sub}</div>
      </div>
    </div>
  );
}

